protected class TranslateTextureSelection : MeshAndTextures
{
    SimpleTuple<Face, Vector2>[] m_FaceAndScale;

    public SimpleTuple<Face, Vector2>[] faceAndScale
    {
        get { return m_FaceAndScale; }
    }

    public TranslateTextureSelection(ProBuilderMesh mesh, PivotPoint pivot)
        : base(mesh, pivot)
    {
        var faces = mesh.faces;

        m_FaceAndScale = mesh.selectedFaceIndexes.Select(x =>
            new SimpleTuple<Face, Vector2>(faces[x], UvUnwrapping.GetUVTransform(mesh, faces[x]).scale))
                .ToArray();
    }
}

if (EditorGUI.EndChangeCheck())
{
    if (!isEditing)
        BeginEdit("Translate Textures");

    m_Position = EditorSnapping.MoveSnap(m_Position);

    // invert `y` because to users it's confusing that "up" in UV space visually moves the texture down
    var delta = new Vector4(m_Position.x, -m_Position.y, 0f, 0f);

    foreach (var value in elementSelection)
    {
        var selection = value as TranslateTextureSelection;

        if (selection == null)
            continue;

        // Account for object scale
        delta *= k_Vector3Magnitude / selection.mesh.transform.lossyScale.magnitude;

        var origins = selection.origins;
        var positions = selection.textures;

        // Translating faces is treated as a special case because we want the textures in scene to visually
        // match the movement of the translation handle. When UVs are scaled, they have the appearance of
        // moving faster or slower (even though they are translating the correct distances). To avoid this,
        // we cache the UV scale of each face and modify the translation delta accordingly. This isn't perfect,
        // as it will not be able to find the scale for sheared or otherwise distorted face UVs. However, for
        // most cases it maps quite well.
        if (ProBuilderEditor.selectMode == SelectMode.TextureFace)
        {
            foreach (var face in selection.faceAndScale)
            {
                var faceDelta = new Vector4(delta.x / face.item2.x, delta.y / face.item2.y, 0f, 0f);

                foreach (var index in face.item1.distinctIndexes)
                    positions[index] = origins[index] + faceDelta;
            }
        }
        else
        {
            foreach (var group in value.elementGroups)
            {
                foreach (var index in group.indices)
                    positions[index] = origins[index] + delta;
            }
        }

        selection.mesh.mesh.SetUVs(k_TextureChannel, positions);
    }
}

EditorHandleUtility.PopMatrix();

class TextureRotateTool : TextureTool
{
    float m_Rotation;
    Vector3 m_Euler;
    Quaternion m_Quaternion;

    protected override void DoToolGUI()
    {
        if (!isEditing)
            m_Rotation = 0f;

        EditorGUI.BeginChangeCheck();

        var size = HandleUtility.GetHandleSize(m_HandlePosition);

        EditorHandleUtility.PushMatrix();

        Handles.matrix = Matrix4x4.TRS(m_HandlePosition, m_HandleRotation, Vector3.one);

        Handles.color = Color.blue;
        m_Euler.z = m_Rotation;
        m_Quaternion = Quaternion.Euler(m_Euler);
        m_Quaternion = Handles.Disc(m_Quaternion, Vector3.zero, Vector3.forward, size, false, EditorSnapping.snapMode == SnapMode.Relative ? EditorSnapping.incrementalSnapRotateValue : 0f);
        m_Euler = m_Quaternion.eulerAngles;
        m_Rotation = m_Euler.z;

        EditorHandleUtility.PopMatrix();

if (EditorGUI.EndChangeCheck())
{
    if (!isEditing)
        BeginEdit("Rotate Textures");

    if (EditorSnapping.snapMode == SnapMode.Relative)
        m_Rotation = EditorSnapping.RotateSnap(m_Rotation);

    foreach (var mesh in elementSelection)
    {
        if (!(mesh is MeshAndTextures))
            continue;
        var mat = (MeshAndTextures) mesh;

        var origins = mat.origins;
        var positions = mat.textures;

        foreach (var group in mat.elementGroups)
        {
            foreach (var index in group.indices)
                positions[index] = mat.postApplyMatrix.MultiplyPoint(
                        Math.RotateAroundPoint(
                            mat.preApplyMatrix.MultiplyPoint3x4(origins[index]), Vector2.zero, -m_Rotation));
        }

        mesh.mesh.mesh.SetUVs(k_TextureChannel, positions);
    }
}

class TextureScaleTool : TextureTool
{
    Vector2 m_Scale;
    float m_UniformScale;


    protected override void DoToolGUI()
    {
        if (!isEditing)
        {
            m_Scale.x = 1f;
            m_Scale.y = 1f;
            m_UniformScale = 1f;
        }

        EditorGUI.BeginChangeCheck();

        var size = HandleUtility.GetHandleSize(m_HandlePosition);

        EditorHandleUtility.PushMatrix();

        Handles.matrix = Matrix4x4.TRS(m_HandlePosition, m_HandleRotation, Vector3.one);

        var snap = EditorSnapping.activeScaleSnapValue;

        Handles.color = Color.red;
        m_Scale.x = Handles.ScaleSlider(m_Scale.x, Vector3.zero, Vector3.right, Quaternion.identity, size, snap.x);

        Handles.color = Color.green;
        m_Scale.y = Handles.ScaleSlider(m_Scale.y, Vector3.zero, Vector3.up, Quaternion.identity, size, snap.y);

        Handles.color = Color.blue;
        m_UniformScale = Handles.ScaleValueHandle(m_UniformScale, Vector3.zero, Quaternion.identity, size, Handles.CubeHandleCap, snap.x);

        EditorHandleUtility.PopMatrix();

if (EditorGUI.EndChangeCheck())
{
    if (!isEditing)
        BeginEdit("Scale Textures");

    var delta = m_Scale * m_UniformScale;

    delta.x = 1f / delta.x;
    delta.y = 1f / delta.y;

    foreach (var mesh in elementSelection)
    {
        if (!(mesh is MeshAndTextures))
            continue;

        var mat = (MeshAndTextures) mesh;
        var origins = mat.origins;
        var positions = mat.textures;

        foreach (var group in mesh.elementGroups)
        {
            foreach (var index in group.indices)
                positions[index] = mat.postApplyMatrix.MultiplyPoint(
                        Vector2.Scale(mat.preApplyMatrix.MultiplyPoint3x4(origins[index]), delta));
        }

        mesh.mesh.mesh.SetUVs(k_TextureChannel, positions);
    }
}

abstract class TextureTool : VertexManipulationTool
{
    const bool k_CollectCoincidentVertices = false;
    protected const int k_TextureChannel = 0;

    protected class MeshAndTextures : MeshAndElementSelection
    {
        List<Vector4> m_Origins;
        List<Vector4> m_Textures;

        Matrix4x4 m_PreApplyMatrix;
        Matrix4x4 m_PostApplyMatrix;

        public Matrix4x4 preApplyMatrix
        {
            get
            {
                return m_PreApplyMatrix;
            }

            private set
            {
                m_PreApplyMatrix = value;
                m_PostApplyMatrix = value.inverse;
            }
        }

        public Matrix4x4 postApplyMatrix
        {
            get
            {
                return m_PostApplyMatrix;
            }

            private set
            {
                m_PostApplyMatrix = value;
                m_PreApplyMatrix = value.inverse;
            }
        }

    public List<Vector4> textures
    {
        get { return m_Textures; }
    }

    public List<Vector4> origins
    {
        get { return m_Origins; }
    }

    public MeshAndTextures(ProBuilderMesh mesh, PivotPoint pivot) : base(mesh, k_CollectCoincidentVertices)
    {
        m_Textures = new List<Vector4>();
        mesh.GetUVs(k_TextureChannel, m_Textures);
        m_Origins = new List<Vector4>(m_Textures);
        preApplyMatrix = Matrix4x4.Translate(-Bounds2D.Center(m_Origins, mesh.selectedIndexesInternal));
    }
}

protected override void OnToolEngaged()
{
    MeshSelection.InvalidateCaches();
}

protected override void OnToolDisengaged()
{
    var isFaceMode = ProBuilderEditor.selectMode.ContainsFlag(SelectMode.TextureFace | SelectMode.Face);

    foreach (var mesh in elementSelection)
    {
        if (!(mesh is MeshAndTextures))
            continue;

        var textures = ((MeshAndTextures)mesh).textures;
        mesh.mesh.SetUVs(k_TextureChannel, textures);

        if (isFaceMode)
        {
            UvUnwrapping.SetAutoAndAlignUnwrapParamsToUVs(mesh.mesh, mesh.mesh.selectedFacesInternal.Where(x => !x.manualUV));
        }
        else
        {
            var indices = new HashSet<int>(mesh.elementGroups.SelectMany(x => x.indices));

            foreach (var face in mesh.mesh.facesInternal)
            {
                foreach (var index in face.distinctIndexesInternal)
                {
                    if (indices.Contains(index))
                    {
                        face.manualUV = true;
                        break;
                    }
                }
            }
        }
    }
}

